INSERT INTO public.words (word, meaning, context, poetry, image_url, status) VALUES
('Cam bù', 'Giống cam vỏ dày, vị ngọt đậm đặc trưng vùng Hương Sơn', 'Tết đến nhà nào cũng bày đĩa cam bù đỏ au trên bàn thờ gia tiên.', 'Cam bù Hương Sơn thơm lừng / Đón xuân sum họp tưng bừng quê hương.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQVIf6FhKsMCdU_D0BfGmZILLv3MQNg5qj5tv7mJztPwAKLn3gXISdxk4402O4jFPLfC0xo_kefrX7FRGMOmFV8aPx1URicTl-fqTCtbbLLsQ&s=10', 'approved'),
('Cươi', 'Sân trước nhà', 'Quét sạch cái cươi rồi trải chiếu ra ngồi hóng gió.', 'Trăng lên soi sáng khoảng cươi / Tiếng cười rộn rã niềm vui sum vầy.', 'https://saigonhoa.com/wp-content/uploads/2021/10/vuon-nha-ngay-xua.jpg', 'approved'),
('Trộ', 'Cơn, đợt (thường dùng chỉ mưa hoặc gió)', 'Trời vừa đổ một trộ mưa rào làm dịu hẳn cái oi bức.', 'Trộ mưa rào tưới mát đồng xanh / Cây lúa vươn mình trổ hạt lành.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=600&auto=format&fit=crop&q=80', 'approved'),
('Lụt', 'Nước lũ dâng cao ngập đồng ruộng, làng mạc', 'Mùa mưa bão bà con chủ động kê cao đồ đạc phòng khi nước lụt.', 'Qua mùa mưa lụt gian nan / Tình người xứ Nghệ càng thêm đậm đà.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSasVe8MT5BBzzFD9MojyacMfwr0nDnKlP2iLbuMNh6aA&s=10', 'approved'),
('Đập', 'Công trình ngăn nước tưới tiêu (như đập Kẻ Gỗ)', 'Nước từ đập Kẻ Gỗ dẫn về tưới mát cho cả vùng đồng bằng.', 'Người đi xây hồ Kẻ Gỗ / Cho đồng lúa xanh ngát bốn mùa.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRl0WIQC2c0giyygMjuuFgHV4Xu2zZ3p87Tu3heZztKoA&s=10', 'approved'),
('Chạc', 'Dây thừng bện chắc dùng buộc trâu bò hoặc đồ vật', 'Cầm sợi chạc buộc lại bó rơm cho chặt kẻo rơi dọc đường.', 'Sợi chạc bền bỉ buộc rơm vàng / Theo chân người nông dân ra đồng.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS-et1wEHuKm0c1aU4wpkhQp5rQINNRs9F6667C81HNMA&s=10', 'approved'),
('Bưởi Phúc Trạch', 'Giống bưởi đặc sản nổi tiếng của vùng Hương Khê, Hà Tĩnh', 'Mùa thu về, bưởi Phúc Trạch chín vàng, múi mọng nước ngọt thanh.', 'Bưởi Phúc Trạch ngọt thanh hương đất / Gửi tình Hương Khê đến muôn nơi.', NULL, 'approved'),
('Mực nhảy', 'Mực tươi vừa đánh bắt lên từ biển Vũng Áng còn tươi rói', 'Mực nhảy Vũng Áng hấp gừng giữ trọn vị ngọt tự nhiên của biển.', 'Biển xanh Vũng Áng sóng xô / Mực nhảy tươi rói đón chờ khách xa.', NULL, 'approved'),
('Cháo canh', 'Món sợi bột mì hoặc bột gạo nấu nước dùng xương, chả, hành lá', 'Sáng ni ăn tô cháo canh nóng hổi rắc thêm chút tiêu cay.', 'Cháo canh đậm vị quê nhà / Sáng mai ấm bụng bước ra giảng đường.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRV7IGxtWVOOVlIKBLhHjKroRMSTbWZWCK51XblczZjeQ&s=10', 'approved'),
('Bánh bèo', 'Bánh làm từ bột lọc nhân tôm thịt hoặc đậu xanh ăn kèm nước mắm', 'Chiều tan học, mấy đứa bạn rủ nhau đi ăn đĩa bánh bèo nóng.', 'Bánh bèo dẻo trong hương vị quê / Nhớ hoài quán nhỏ lúc đi về.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRLpc9Rfje9gIzMHT2spTPyE0NhU87h3WWTWbSda58AJA&s=10', 'approved'),
('Bánh ngào', 'Bánh làm từ bột nếp viên tròn nấu trong nước mật mía gừng', 'Trời se lạnh mà ăn bát bánh ngào nóng hổi thì ấm bụng vô cùng.', 'Bánh ngào quyện vị gừng cay / Mật mía ngọt lịm những ngày đông sang.', NULL, 'approved'),
('Chõng tre', 'Giường thấp làm bằng tre đặt ngoài sân hoặc hiên hóng mát', 'Tối trăng sáng, cả nhà trải chiếu lên chõng tre ngồi kể chuyện.', 'Chõng tre kẽo kẹt đêm trăng sáng / Bà kể chuyện xưa ấm tuổi thơ.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSymxydqu6zPBcedoJYlMWJIegD7Ew3sBZSMg85rP6EzA&s=10', 'approved'),
('Nồi bung', 'Nồi gang hoặc đồng cỡ lớn dùng nấu cơm, nấu cám', 'Ngày giỗ họ, nhà mô cũng bắc nồi bung nấu cơm đãi khách.', 'Nồi bung cơm dẻo thơm mùi mới / Đậm đà tình nghĩa chốn quê nhà.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRoNupDGBx8tRcJp_oHC95w3ypzgFpe0qS8Zot2DQqEfg&s=10', 'approved'),
('Đòn', 'Ghế đẩu nhỏ, thấp bằng gỗ hoặc tre', 'Kéo cái đòn lại đây ngồi uống bát nước chè xanh cho mát.', 'Chiếc đòn tre nhỏ đặt bên hiên / Chuyện trò xóm giềng ấm tình duyên.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ4OfNk30jo2Tk4NcU3nPkpYXCLWGeD2qVUd6K9DvPrxg&s=10', 'approved'),
('Chạn', 'Tủ đựng bát đũa, thức ăn trong bếp', 'Cất đĩa cá kho vào trong chạn kẻo con mèo ăn mất.', 'Gian bếp đơn sơ chiếc chạn tre / Lưu giữ hương cơm ấm trưa hè.', NULL, 'approved'),
('Mương', 'Rãnh dẫn nước tưới tiêu ngoài đồng', 'Sáng mai cả xóm ra khơi thông con mương dẫn nước vào ruộng.', 'Nước mương trong mát chảy về đồng / Nuôi cây lúa trổ đượm hương nồng.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRphHX_TLhGLPvKmEyk8iPLnA9NpXxInJNyJ-F4msaxyQ&s=10', 'approved'),
('Lộ', 'Đường cái, đường lớn', 'Đi ra ngoài lộ đón xe khách lên thành phố.', 'Đường lộ thênh thang nối xóm làng / Đón người đi xa bước vẻ vang.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQS3gxjLC4Lf81DiaBCH38WhDtxmnlecMRbe29Y19JgDQ&s=10', 'approved'),
('Trốc', 'Đầu', 'Nắng trưa gay gắt nhớ đội nón kẻo đau trốc.', 'Trốc đội nón mê che nắng gió / Vai gầy gồng gánh cả quê hương.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS_zB1y3WUUNhMYZpdGO47_KNln2CFl1GhJfbBbDZd-8Q&s=10', 'approved'),
('Đọi', 'Cái bát ăn cơm.', 'Đưa cái đọi mạ múc canh cu nớ ăn cơm nựa!', 'Chén tình nghĩa đượm tình quê / Bát cơm dẻo thơm, đọi canh chan chứa tình người.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQcaJLNWtZtrhIZ2LbetrXylQx9_xVN187orOTHwhCiOA&s=10', 'approved'),
('Ngái', 'Xa, khoảng cách địa lý xa xôi.', 'Nhà ở ngái rứa mà chiều mô nỏ rảnh rỗi ghé chơi.', 'Đường về xứ Nghệ dẫu ngái xa / Có câu ví giặm đậm đà lòng ai.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=600&auto=format&fit=crop&q=80', 'approved'),
('Nỏ', 'Không (Phó từ phủ định đặc trưng xứ Nghệ).', 'Hắn có biết chi mô mà hỏi, nỏ nói năng chi cả.', 'Nỏ qua được gió Lào cát trắng / Mà thương nhau đến trọn vẹn cuộc đời.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQW__8VF0U3BBl0k2-qbeMgx4cVJcgKnDeNxApjB0QmdA&s=10', 'approved'),
('Trốc cúi', 'Đầu gối.', 'Đi ngã mô mà va cái trốc cúi vào bàn bầm tím cả.', 'Mồ hôi rơi ướt đẫm trốc cúi gầy / Mạ gồng gánh nuôi con qua ngày giông bão.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRxZVIXAC0Sc1Z3QqW0NNwi1FAeaR3wIyK_8S1ZD0HatQ&s=10', 'approved'),
('Mấn', 'Váy, trang phục truyền thống của phụ nữ xưa.', 'Mạ mặc cái mấn sồi đi hội làng từ sớm.', 'Nón mê chiếc mấn buông lơi / Duyên quê xứ Nghệ trọn đời khó phai.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSKhWpJntu43RBxT6VM059ldmcDl5q0UV2j_B13AEfwGQ&s=10', 'approved');
